window.VOIX_ADD&&window.VOIX_ADD({"humeur-0": {"t": "Bonjour mon cœur ! Tu as bien dormi ?", "src": "data:audio/mpeg;base64,"}, "humeur-1": {"t": "(J’ai encore un peu sommeil… mais je fais un effort.)", "src": "data:audio/mpeg;base64,"}, "humeur-2": {"t": "Bonjour Maman ! Oui, j’ai bien dormi.", "src": "data:audio/mpeg;base64,"}, "humeur-3": {"t": "Ton sourire, ça me fait plaisir pour toute la journée !", "src": "data:audio/mpeg;base64,"}, "humeur-pourquoi": {"t": "Le matin, la bonne humeur, c'est comme un rayon de soleil : elle se partage ! Si je souris et que je dis bonjour, toute la famille commence bien la journée. Et si je suis grognon, je peux le dire gentiment : « J'ai besoin d'un câlin. »", "src": "data:audio/mpeg;base64,"}});
